window.__LIMG={"L0":"data:image/jpeg;base64,","L1":"data:image/jpeg;base64,","L2":"data:image/jpeg;base64,"};
(function(){var M=window.__LIMG||{};
function fix(s){return s.replace(/__IMGREF_(L\d+)__/g,function(_,k){return M[k]||''})}
document.querySelectorAll('[data-bg]').forEach(function(e){
  e.style.backgroundImage="url('"+fix(e.getAttribute('data-bg'))+"')";
  e.removeAttribute('data-bg');});})();